meaning_id":"hari pengumpulan sampah","meaning_en":null,"extra":{"chapter_number":35,"chapter_title":"Pola N4 Lanjutan yang Sering Dipakai","sort_order":59,"romaji":"kaishuubi","category":"Waktu","jenis":"KB","curriculum":"KOJAC","dataset":"vocabulary_phase2_b02_35"},"is_published":true}]$kojac_gate4a$::jsonb as payload
),
canonical as (
  select
    x.id::uuid as id,
    x.item_type,
    x.jlpt_level,
    x.prompt,
    x.reading,
    x.meaning_id,
    x.meaning_en,
    x.extra,
    x.is_published
  from canonical_payload p,
       jsonb_to_recordset(p.payload) as x(
         id text,
         item_type text,
         jlpt_level text,
         prompt text,
         reading text,
         meaning_id text,
         meaning_en text,
         extra jsonb,
         is_published boolean
       )
),
remote_vocab as (
  select *
  from public.learning_items
  where item_type = 'vocabulary'
),
canonical_presence as (
  select
    c.*,
    li.id as remote_id,
    case
      when li.id is null then 'NOT_PRESENT'
      when li.item_type is not distinct from c.item_type
       and li.jlpt_level is not distinct from c.jlpt_level
       and li.prompt is not distinct from c.prompt
       and li.reading is not distinct from c.reading
       and li.meaning_id is not distinct from c.meaning_id
       and li.meaning_en is not distinct from c.meaning_en
       and li.extra is not distinct from c.extra
       and li.is_published is not distinct from c.is_published
      then 'PRESENT_IDENTICAL'
      else 'PRESENT_MISMATCH'
    end as presence_status
  from canonical c
  left join public.learning_items li on li.id = c.id
),
canonical_mismatch_detail as (
  select
    c.id,
    c.prompt,
    array_remove(array[
      case when li.item_type is distinct from c.item_type then 'item_type' end,
      case when li.jlpt_level is distinct from c.jlpt_level then 'jlpt_level' end,
      case when li.prompt is distinct from c.prompt then 'prompt' end,
      case when li.reading is distinct from c.reading then 'reading' end,
      case when li.meaning_id is distinct from c.meaning_id then 'meaning_id' end,
      case when li.meaning_en is distinct from c.meaning_en then 'meaning_en' end,
      case when li.extra is distinct from c.extra then 'extra' end,
      case when li.is_published is distinct from c.is_published then 'is_published' end
    ], null) as differing_fields
  from canonical c
  join public.learning_items li on li.id = c.id
  where li.item_type is distinct from c.item_type
     or li.jlpt_level is distinct from c.jlpt_level
     or li.prompt is distinct from c.prompt
     or li.reading is distinct from c.reading
     or li.meaning_id is distinct from c.meaning_id
     or li.meaning_en is distinct from c.meaning_en
     or li.extra is distinct from c.extra
     or li.is_published is distinct from c.is_published
),
remote_chapter_counts as (
  select
    case
      when coalesce(extra->>'chapter_number','') ~ '^[0-9]+$'
      then (extra->>'chapter_number')::integer
      else null
    end as chapter_number,
    count(*)::bigint as row_count
  from remote_vocab
  group by 1
),
unexpected_rows as (
  select li.id,
         case when coalesce(li.extra->>'chapter_number','') ~ '^[0-9]+$'
              then (li.extra->>'chapter_number')::integer end as chapter_number,
         li.prompt,
         li.reading,
         li.extra->>'dataset' as dataset,
         li.extra->>'curriculum' as curriculum,
         case when coalesce(li.extra->>'sort_order','') ~ '^[0-9]+$'
              then (li.extra->>'sort_order')::integer end as sort_order
  from remote_vocab li
  where coalesce(li.extra->>'chapter_number','') ~ '^[0-9]+$'
    and (li.extra->>'chapter_number')::integer between 2 and 35
    and not exists (select 1 from canonical c where c.id = li.id)
),
remote_lexical_duplicates as (
  select prompt, coalesce(reading,'') as normalized_reading, count(*)::bigint as row_count
  from public.learning_items
  where item_type='vocabulary'
  group by prompt, coalesce(reading,'')
  having count(*) > 1
),
remote_sort_duplicates as (
  select (extra->>'chapter_number')::integer as chapter_number,
         (extra->>'sort_order')::integer as sort_order,
         count(*)::bigint as row_count
  from remote_vocab
  where coalesce(extra->>'chapter_number','') ~ '^[0-9]+$'
    and coalesce(extra->>'sort_order','') ~ '^[0-9]+$'
    and (extra->>'chapter_number')::integer between 2 and 35
  group by 1,2
  having count(*) > 1
),
sort_collisions_with_unexpected as (
  select u.id, u.chapter_number, u.sort_order, u.prompt, u.reading
  from unexpected_rows u
  where exists (
    select 1 from canonical c
    where (c.extra->>'chapter_number')::integer = u.chapter_number
      and (c.extra->>'sort_order')::integer = u.sort_order
  )
),
lexical_key_collisions as (
  select li.id as remote_id,
         c.id as canonical_id,
         c.prompt,
         c.reading
  from canonical c
  join public.learning_items li
    on li.item_type='vocabulary'
   and li.prompt=c.prompt
   and coalesce(li.reading,'')=coalesce(c.reading,'')
   and li.id<>c.id
),
non_vocab_uuid_collisions as (
  select li.id, li.item_type, c.prompt
  from canonical c
  join public.learning_items li on li.id=c.id
  where li.item_type <> 'vocabulary'
),
expected_columns as (
  select * from (values
    ('id','uuid'),
    ('item_type','text'),
    ('jlpt_level','text'),
    ('prompt','text'),
    ('reading','text'),
    ('meaning_id','text'),
    ('meaning_en','text'),
    ('extra','jsonb'),
    ('is_published','boolean')
  ) v(column_name, data_type)
),
actual_columns as (
  select column_name,
         case when data_type='USER-DEFINED' then udt_name else data_type end as data_type
  from information_schema.columns
  where table_schema='public' and table_name='learning_items'
    and column_name in ('id','item_type','jlpt_level','prompt','reading','meaning_id','meaning_en','extra','is_published')
),
schema_mismatch as (
  select e.column_name, e.data_type as expected_type, a.data_type as actual_type
  from expected_columns e
  left join actual_columns a using(column_name)
  where a.column_name is null or a.data_type <> e.data_type
),
review_fk as (
  select con.conname,
         pg_get_constraintdef(con.oid) as definition
  from pg_constraint con
  join pg_class rel on rel.oid=con.conrelid
  join pg_namespace nsp on nsp.oid=rel.relnamespace
  where nsp.nspname='public'
    and rel.relname='review_progress'
    and con.contype='f'
    and pg_get_constraintdef(con.oid) ilike '%learning_items%'
),
lexical_index as (
  select indexname, indexdef
  from pg_indexes
  where schemaname='public'
    and tablename='learning_items'
    and indexdef ilike '%unique%'
    and indexdef ilike '%item_type%'
    and indexdef ilike '%prompt%'
    and indexdef ilike '%reading%'
)
select jsonb_build_object(
  'schema', jsonb_build_object(
    'learning_items_exists', to_regclass('public.learning_items') is not null,
    'schema_mismatch_count', (select count(*) from schema_mismatch),
    'schema_mismatches', coalesce((select jsonb_agg(to_jsonb(s)) from schema_mismatch s), '[]'::jsonb),
    'lexical_unique_index_candidates', coalesce((select jsonb_agg(to_jsonb(i)) from lexical_index i), '[]'::jsonb)
  ),
  'review_progress', jsonb_build_object(
    'exists', to_regclass('public.review_progress') is not null,
    'fk_to_learning_items', coalesce((select jsonb_agg(to_jsonb(f)) from review_fk f), '[]'::jsonb),
    'aggregate_rows', (select count(*) from public.review_progress)
  ),
  'vocabulary_counts', jsonb_build_object(
    'all_vocabulary', (select count(*) from remote_vocab),
    'bab1', (select count(*) from remote_vocab where extra->>'chapter_number'='1'),
    'bab2_35', (select count(*) from remote_vocab where coalesce(extra->>'chapter_number','') ~ '^[0-9]+$' and (extra->>'chapter_number')::integer between 2 and 35),
    'invalid_or_missing_chapter', (select count(*) from remote_vocab where not (coalesce(extra->>'chapter_number','') ~ '^[0-9]+$' and (extra->>'chapter_number')::integer between 1 and 35)),
    'by_chapter', coalesce((select jsonb_object_agg(coalesce(chapter_number::text,'INVALID'), row_count order by chapter_number) from remote_chapter_counts), '{}'::jsonb)
  ),
  'canonical_uuid_check', jsonb_build_object(
    'canonical_total', (select count(*) from canonical),
    'not_present', (select count(*) from canonical_presence where presence_status='NOT_PRESENT'),
    'present_identical', (select count(*) from canonical_presence where presence_status='PRESENT_IDENTICAL'),
    'present_mismatch', (select count(*) from canonical_presence where presence_status='PRESENT_MISMATCH'),
    'mismatch_details', coalesce((select jsonb_agg(to_jsonb(m)) from canonical_mismatch_detail m), '[]'::jsonb)
  ),
  'collisions', jsonb_build_object(
    'uuid_non_vocabulary', (select count(*) from non_vocab_uuid_collisions),
    'uuid_non_vocabulary_details', coalesce((select jsonb_agg(to_jsonb(x)) from non_vocab_uuid_collisions x), '[]'::jsonb),
    'lexical_key', (select count(*) from lexical_key_collisions),
    'lexical_key_details', coalesce((select jsonb_agg(to_jsonb(x)) from lexical_key_collisions x), '[]'::jsonb),
    'unexpected_noncanonical_bab2_35', (select count(*) from unexpected_rows),
    'unexpected_rows', coalesce((select jsonb_agg(to_jsonb(x) order by chapter_number, sort_order, prompt) from unexpected_rows x), '[]'::jsonb),
    'remote_duplicate_lexical_identity', (select count(*) from remote_lexical_duplicates),
    'remote_duplicate_lexical_details', coalesce((select jsonb_agg(to_jsonb(x)) from remote_lexical_duplicates x), '[]'::jsonb),
    'remote_duplicate_chapter_sort_order', (select count(*) from remote_sort_duplicates),
    'remote_duplicate_sort_details', coalesce((select jsonb_agg(to_jsonb(x)) from remote_sort_duplicates x), '[]'::jsonb),
    'unexpected_sort_collisions_with_canonical', (select count(*) from sort_collisions_with_unexpected),
    'unexpected_sort_collision_details', coalesce((select jsonb_agg(to_jsonb(x)) from sort_collisions_with_unexpected x), '[]'::jsonb)
  )
) as gate4a_read_only_preflight;
